<?php require_once __DIR__ . '/../partials/helpers.php'; ob_start(); ?>
<div class="page-header"><div><p class="page-subtitle text-muted mb-0"><a href="/orders">Bestellungen</a></p><h1>Bedarfsmeldungen</h1></div><div class="page-actions"><a class="btn btn-secondary" href="/orders/templates">Bestellvorlagen</a></div></div>
<div class="card card-form mb-4"><div class="card-header"><h2>Bedarf melden</h2></div><form method="post" action="/orders/requests"><?= csrf_field() ?><div class="form-row"><div class="form-group"><label for="article">Artikel</label><select id="article" name="article_id"><option value="">Freie Bezeichnung</option><?php foreach ($articles as $article): ?><option value="<?= (int) $article['id'] ?>"><?= e($article['manufacturer_name'] . ' ' . $article['name']) ?></option><?php endforeach; ?></select></div><div class="form-group"><label for="description">Bezeichnung</label><input id="description" name="description" maxlength="255"></div><div class="form-group"><label for="quantity">Menge</label><input id="quantity" name="quantity" type="number" min="1" required></div></div><div class="form-row"><div class="form-group"><label for="cost_center">Kostenstelle</label><select id="cost_center" name="cost_center_id"><option value="">Keine</option><?php foreach ($costCenters as $cc): ?><option value="<?= (int) $cc['id'] ?>"><?= e($cc['number'] . ' · ' . $cc['description']) ?></option><?php endforeach; ?></select></div><div class="form-group"><label for="note">Begründung / Hinweis</label><input id="note" name="note" maxlength="500"></div></div><button class="btn btn-primary">Bedarf melden</button></form></div>
<div class="card card-flush"><div class="card-header"><h2>Gemeldete Bedarfe</h2></div><?php if (!$requests): ?><div class="table-empty">Keine Bedarfsmeldungen vorhanden.</div><?php else: ?><div class="table-wrapper"><table class="table"><thead><tr><th>Nr.</th><th>Gemeldet von</th><th>Kostenstelle</th><th>Hinweis</th><th>Status</th><th></th></tr></thead><tbody><?php foreach ($requests as $demand): ?><tr><td>#<?= (int) $demand['id'] ?></td><td><?= e($demand['requested_by_name']) ?></td><td><?= e($demand['cost_center_number'] ?? '–') ?></td><td><?= e($demand['note'] ?? '–') ?></td><td><?= badge($demand['status'] === 'open' ? 'Offen' : 'Übernommen', $demand['status'] === 'open' ? 'warning' : 'success') ?></td><td><?php if ($demand['status'] === 'open' && $can('orders.manage')): ?><form method="post" action="/orders/requests/<?= (int) $demand['id'] ?>/convert" class="flex gap-1"><?= csrf_field() ?><select name="supplier_id" required><option value="">Lieferant</option><?php foreach ($suppliers as $supplier): ?><option value="<?= (int) $supplier['id'] ?>"><?= e($supplier['name']) ?></option><?php endforeach; ?></select><button class="btn btn-secondary btn-sm">In Bestellung übernehmen</button></form><?php elseif ($demand['purchase_order_id']): ?><a href="/orders/<?= (int) $demand['purchase_order_id'] ?>">Bestellung <?= e($demand['order_number']) ?></a><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div>
